mapper.insert:
INSERT INTO chatroom (
    chatroom_no,
    prj_no,
    chatroom_name
) VALUES (
    #{chatroomNo},
    #{prjNo},
    #{chatroomName}
)

mapper.delete:
DELETE FROM chatroom_mem
WHERE chatroom_no = #{chatroomNo}
AND user_id = #{userId}

mapper.update:
UPDATE chatroom_mem
SET read_message_no = #{readMessageNo}
WHERE chatroom_no = #{chatroomNo}
AND user_id = #{userId}

mapper.select:
SELECT 
    COUNT(cm.message_no) as unread_count
FROM chat_message cm
LEFT JOIN chatroom_mem crm ON cm.chatroom_no = crm.chatroom_no 
    AND crm.user_id = #{userId}
WHERE cm.chatroom_no = #{chatroomNo}
AND cm.user_id != #{userId}
AND (crm.read_message_no IS NULL OR cm.message_no > crm.read_message_no)
